2. Implement the `IRestService` interface using `HttpClient` to make REST requests:

```csharp
public abstract class RestServiceBase : IRestService
{
    private readonly HttpClient httpClient;
    private string baseUrl;
    private string authToken;

    protected RestServiceBase(string baseUrl)
    {
        this.baseUrl = baseUrl;
        httpClient = new HttpClient();
    }

    public void SetAuthToken(string authToken)
    {
        this.authToken = authToken;
    }

    private async Task<HttpResponseMessage> SendRequestAsync(string method, string endpoint, object body = null)
    {
        var requestUri = $"{baseUrl}/{endpoint}";
        var requestMessage = new HttpRequestMessage(new HttpMethod(method), requestUri);

        if (body != null)
        {
            requestMessage.Content = new StringContent(JsonConvert.SerializeObject(body));
            requestMessage.Content.Headers.Add("Content-Type", "application/json");
        }

        if (!string.IsNullOrWhiteSpace(authToken))
        {
            requestMessage.Headers.Authorization = new AuthenticationHeaderValue("Bearer", authToken);
        }

        return await httpClient.SendAsync(requestMessage);
    }

    public Task<T> GetAsync<T>(string endpoint)
    {
        return SendRequestAsync("GET", endpoint).ContinueWith<Task<T>>((response) =>
        {
            response.EnsureSuccessStatusCode();
            return JsonConvert.DeserializeObject<T>(response.Content.ReadAsStringAsync().Result);
        });
    }

